struct Entry { id: String, active: bool }
pub fn collect(entries: Vec<Entry>) -> HashMap<String, Entry> {
    entries.into_iter().filter(|entry| entry.active)
        .map(|entry| (entry.id.clone(), entry)).collect()
}
